"""Trace Recovery from the Full Order-Two Free Witness."""

from __future__ import annotations

import math
from typing import Optional, Tuple


def divisor_power_sum(n: int, k: int) -> int:
    """sigma_k(n) = sum over d | n of d^k, by trial-division enumeration."""
    total: int = 0
    i: int = 1
    while i * i <= n:
        if n % i == 0:
            total += i ** k
            j: int = n // i
            if j != i:
                total += j ** k
        i += 1
    return total


def recover_factors_from_witness(n: int, w: int) -> Optional[Tuple[int, int]]:
    """Recover the two prime factors of N = p*q from w = sigma_2(N).

    Steps (all exact integer arithmetic):
      1. r = w + 2N - N^2 - 1 must equal (p+q)^2;
      2. t = isqrt(r) is the trace p + q;
      3. s = t^2 - 4N must equal (q-p)^2;
      4. d = isqrt(s) is the difference q - p;
      5. return ((t-d)/2, (t+d)/2).
    Returns None if any perfect-square test fails, i.e. if (N, w) is not the
    witness of a two-factor decomposition.
    """
    r: int = w + 2 * n - n * n - 1
    if r < 0:
        return None
    t: int = math.isqrt(r)
    if t * t != r:
        return None
    s: int = t * t - 4 * n
    if s < 0:
        return None
    d: int = math.isqrt(s)
    if d * d != s or (t - d) % 2 != 0:
        return None
    return ((t - d) // 2, (t + d) // 2)


if __name__ == "__main__":
    for p, q in [(11, 17), (53, 61), (1000003, 1000033)]:
        n: int = p * q
        w: int = (1 + p * p) * (1 + q * q)
        print(f"N = {n:<16} sigma_2(N) = {w:<26} "
              f"recovered = {recover_factors_from_witness(n, w)}")
    # Cross-check the closed form against a genuine divisor-sum evaluation.
    w187: int = divisor_power_sum(187, 2)
    print(f"sigma_2(187) by enumeration = {w187}, "
          f"recovered = {recover_factors_from_witness(187, w187)}")

"""Certified Small-Prime Modulus Search with a Separation Certificate."""

from __future__ import annotations

from typing import Dict, List, Optional, Tuple


def primes_below(x: int) -> List[int]:
    """Sieve of Eratosthenes: all primes strictly below x."""
    if x <= 2:
        return []
    sieve: List[bool] = [True] * x
    sieve[0] = sieve[1] = False
    i: int = 2
    while i * i < x:
        if sieve[i]:
            for j in range(i * i, x, i):
                sieve[j] = False
        i += 1
    return [i for i in range(x) if sieve[i]]


def witness(k: int, a: int, b: int) -> int:
    """W_k(a,b) = (1 + a^k)(1 + b^k)."""
    return (1 + a ** k) * (1 + b ** k)


def certified_prime_modulus(
    p: int, q: int, k: int = 2, bound: int = 200
) -> Optional[Tuple[int, Dict[str, int]]]:
    """Find a prime modulus r < bound whose residue determines {p,q},
    together with a separation certificate.

    The certificate records the residues of the two competing witnesses --
    the prime factorisation and the trivial factorisation 1 * N -- proving
    that they are distinguished modulo r.  Guaranteed to succeed whenever
    the number of primes below `bound` exceeds omega(G_k), and in particular
    whenever pi(bound) > log2(G_k).
    """
    gap: int = (p ** k - 1) * (q ** k - 1)
    n: int = p * q
    for r in primes_below(bound):
        if gap % r != 0:
            return r, {
                "modulus": r,
                "witness_prime_mod": witness(k, p, q) % r,
                "witness_trivial_mod": witness(k, 1, n) % r,
                "gap_mod": gap % r,
            }
    return None


if __name__ == "__main__":
    for p, q in [(11, 17), (101, 103), (10007, 10009), (1000003, 1000033)]:
        result = certified_prime_modulus(p, q)
        print(f"p={p:<9} q={q:<9} ->", result)
